import { execFile } from "node:child_process";
function runGit(args, cwd) {
    return new Promise((resolve, reject) => {
        execFile("git", args, { cwd, encoding: "utf8", maxBuffer: 20 * 1024 * 1024 }, (error, stdout, stderr) => {
            if (error) {
                reject(new Error(`git ${args.join(" ")} 실패: ${stderr.trim() || error.message}`));
                return;
            }
            resolve(stdout);
        });
    });
}
export function parseChangedDocuments(output) {
    const values = output.split("\0").filter((value) => value.length > 0);
    const documents = [];
    for (let index = 0; index < values.length;) {
        const status = values[index++];
        if (status.startsWith("R")) {
            const previousPath = values[index++];
            const path = values[index++];
            if (previousPath && path) {
                documents.push({ status: "renamed", previousPath, path });
            }
            continue;
        }
        const path = values[index++];
        if (!path) {
            continue;
        }
        documents.push({
            status: status === "A" ? "added" : "modified",
            path,
        });
    }
    return documents;
}
export async function getChangedDocuments(cwd, baseSha, headSha) {
    const output = await runGit([
        "diff",
        "--name-status",
        "-z",
        "--find-renames",
        "--diff-filter=AMR",
        baseSha,
        headSha,
        "--",
        "*.md",
        "*.mdx",
    ], cwd);
    return parseChangedDocuments(output);
}
export async function getDocumentAtRevision(cwd, revision, path) {
    try {
        return await runGit(["show", `${revision}:${path}`], cwd);
    }
    catch {
        return undefined;
    }
}
export async function getDocumentDiff(cwd, baseSha, headSha, path) {
    return runGit([
        "diff",
        "--unified=0",
        "--no-color",
        baseSha,
        headSha,
        "--",
        path,
    ], cwd);
}
export function getChangedLineNumbers(diff) {
    const lines = new Set();
    for (const line of diff.split(/\r?\n/)) {
        const match = /^@@ -\d+(?:,\d+)? \+(\d+)(?:,(\d+))? @@/.exec(line);
        if (!match) {
            continue;
        }
        const start = Number(match[1]);
        const count = match[2] == null ? 1 : Number(match[2]);
        for (let offset = 0; offset < count; offset += 1) {
            lines.add(start + offset);
        }
    }
    return lines;
}
export function hasDocumentContentChanges(diff) {
    return /^@@ /m.test(diff);
}
